ee:variables.ee:set-variable:
%dw 2.0
import contactFields, soqlIdList from modules::crm
output application/java
var q = attributes.queryParams default {}
var hasIds = not isEmpty(q.ids default "")
var hasSearch = (q.email != null) or (q.phone != null)
var size = (q.size default 20) as Number
var page = (q.page default 1) as Number
---
if (hasIds and hasSearch) { invalid: true }
else if (hasIds) { soql: "SELECT " ++ contactFields ++ " FROM Contact WHERE Id IN (" ++ soqlIdList(q.ids) ++ ") ORDER BY Name", params: {} }
else if (hasSearch) {
	soql: "SELECT " ++ contactFields ++ " FROM Contact WHERE "
		++ ([ (if (q.email != null) "Email = ':email'" else null), (if (q.phone != null) "Phone = ':phone'" else null) ] filter ($ != null) joinBy " OR ")
		++ " ORDER BY Name",
	params: { (email: q.email) if (q.email != null), (phone: q.phone) if (q.phone != null) }
}
else { soql: "SELECT " ++ contactFields ++ " FROM Contact ORDER BY Name LIMIT " ++ size ++ " OFFSET " ++ ((page - 1) * size), params: {} }

ee:message.ee:set-payload:
%dw 2.0
output application/java
var item = payload.items[0] default {}
// Status codes of the failed record (SaveResult errors): DUPLICATES_DETECTED from the duplicate rule (existing email)
// or DUPLICATE_VALUE from the unique Email_Key__c (two inserts at the same time)
var codes = ((item.payload.errors default []) map ((e) -> e.statusCode default "")) ++ [item.statusCode default ""]
---
if (item.successful default false) { created: true, duplicate: false, id: item.id }
else if ((codes contains "DUPLICATES_DETECTED") or (codes contains "DUPLICATE_VALUE")) { created: false, duplicate: true }
else { created: false, duplicate: false, message: item.message default (codes joinBy " ") }
